/* FICHIER GÉNÉRÉ par outils/embarquer-donnees.py — ne pas modifier à la main.
   Copie de assets/data/*.json pour le jeu en double-clic (file://). */
window.VML_DONNEES_EMBARQUEES = {"enigmes":{"_commentaire":"Énigmes du jeu « Vingt mille lieues sous les mers — Le Journal du Nautilus ». Chaque énigme porte sa fiche d'ancrage narratif (cahier des charges § 3 bis) et un bloc par grade (mousse, matelot, timonier, lieutenant, second) : données, consigne, indices, type éventuellement différent, justification (lieutenant, second). Le rendu des types vient de commun/js/enigmes.js (non modifié) ; le type « circuit » est propre au jeu (js/type-circuit.js).","version":1,"niveaux":[{"id":"mousse","nom":"Mousse","icone":"🐚","equivalent":"≈ CE2","profil":"énigmes courtes, vocabulaire simple, aides renforcées (premier indice offert, un choix faux écarté, fiche mise en évidence)"},{"id":"matelot","nom":"Matelot","icone":"⚓","equivalent":"≈ CM1","profil":"cœur de programme CM1"},{"id":"timonier","nom":"Timonier","icone":"🧭","equivalent":"≈ CM2","profil":"cœur de programme CM2"},{"id":"lieutenant","nom":"Lieutenant","icone":"🔭","equivalent":"≈ 6ᵉ","profil":"raisonnement en deux étapes, documents à croiser, justification"},{"id":"second","nom":"Second","icone":"🔱","equivalent":"≈ 5ᵉ","profil":"synthèse, données chiffrées, pièges de logique, justification"}],"escales":[{"numero":2,"id":"ventre-du-nautilus","titre":"Dans le ventre du Nautilus","lieu":"À bord du Nautilus, sous le Pacifique, novembre 1867","matiere":"Sciences et technologie","periode_conseillee":"P3 (Année A, avec « L'électricité ») ou P1 (avec « Les objets techniques »)","episode":"Première partie, ch. XI « Le Nautilus », ch. XII « Tout par l'électricité », ch. XIII « Quelques chiffres »","scenarimage":"scenarimages/escale-02.md","decor_ouverture":"salon","mot":"MOBILIS","mot_origine":"Devise du Nautilus, « Mobilis in mobili » (mobile dans l'élément mobile), dans le roman marquée sur les objets du bord avec la lettre N.","air":{"depart":100,"apres_avarie":62,"perte_par_minute":1,"perte_par_indice":3,"plancher":25},"enigmes":[{"id":"e2-1","escale":2,"ordre":1,"titre":"Le câble brûlé du carré","decor":"carre","objet_principal":"table","objets_cliquables":["table","journal","tableau-cadrans"],"personnage_emetteur":"conseil","probleme_narratif":"Un câble a perdu sa gaine et touché la table mouillée : court-circuit, début d'incendie, journal de bord et cartes brûlés. Pour refaire un câble, Conseil veut trier les objets posés sur la table : ceux qui laissent passer le courant (pour l'âme du câble) et ceux qui l'arrêtent (pour la gaine).","enjeu":"Sans câble neuf, le courant ne peut pas revenir : pas de lumière, pas de pompe à air.","episode_du_roman":"Partie I, ch. XII « Tout par l'électricité » : tout, à bord, fonctionne à l'électricité (vraisemblance : un câble abîmé suffit à tout arrêter). L'avarie elle-même est une invention du jeu.","competence_programme":"Électricité : distinguer conducteurs et isolants ; connaître les dangers de l'électricité (court-circuit, eau salée).","pourquoi_ce_savoir_ici":"Un câble, c'est une âme qui conduit et une gaine qui isole : on ne peut pas le refaire sans savoir quels matériaux laissent passer le courant.","reaction_du_decor":{"effet":"cable-neuf","description":"Un câble neuf (cuivre gainé de caoutchouc) apparaît sur la table ; la fumée du carré se dissipe."},"liberte_ou_anachronisme":"Avarie inventée (court-circuit, début d'incendie). Isolation simplifiée : les câbles sous-marins des années 1858-1866 étaient isolés à la gutta-percha ; le jeu parle de caoutchouc, isolant connu des élèves (voir A-VERIFIER.md).","lecon":"conducteurs-isolants","type":"tri","niveau_variantes":"Mousse : 6 objets. Matelot : 8 objets. Timonier : 9 objets dont la mine de crayon et l'eau de mer. Lieutenant : 10 objets + justification. Second : QCM sur le carnet d'essais de Conseil (galvanomètre) + justification.","mousse":{"dialogue":"Ce câble a brûlé. Je propose de ranger avant d'agir : d'un côté ce qui laisse passer le courant, de l'autre ce qui l'arrête.","consigne":"Range chaque objet de la table dans la bonne colonne.","colonnes":[{"id":"conducteur","titre":"Laisse passer le courant","icone":"⚡"},{"id":"isolant","titre":"Arrête le courant","icone":"🛑"}],"cartes":[{"txt":"un fil de cuivre","icone":"🧵","col":"conducteur"},{"txt":"une clé en fer","icone":"🗝️","col":"conducteur"},{"txt":"une cuillère en argent","icone":"🥄","col":"conducteur"},{"txt":"une règle en laiton","icone":"📏","col":"conducteur"},{"txt":"un verre en cristal","icone":"🥃","col":"isolant"},{"txt":"un bouchon de liège","icone":"🍾","col":"isolant"},{"txt":"une feuille de papier","icone":"📄","col":"isolant"},{"txt":"un ruban de caoutchouc","icone":"⬛","col":"isolant"}],"indices":["Ouvre la fiche « Conducteurs et isolants » dans la Bibliothèque : cherche la famille des métaux.","Le fer, l'argent et le laiton sont tous des métaux."]},"matelot":{"dialogue":"Monsieur le professeur dirait : « méthode d'abord ». Classons ces objets : ce qui conduit le courant servira à l'âme du câble, ce qui l'isole servira à la gaine.","consigne":"Classe les huit objets posés sur la table : <b>conducteur</b> ou <b>isolant</b> ?","colonnes":[{"id":"conducteur","titre":"Conducteur (pour l'âme du câble)","icone":"⚡"},{"id":"isolant","titre":"Isolant (pour la gaine)","icone":"🛑"}],"cartes":[{"txt":"un compas en acier","icone":"📐","col":"conducteur"},{"txt":"une clé en fer","icone":"🗝️","col":"conducteur"},{"txt":"un fil de cuivre","icone":"🧵","col":"conducteur"},{"txt":"une plume d'écriture en acier","icone":"✒️","col":"conducteur"},{"txt":"une carafe en verre","icone":"🫙","col":"isolant"},{"txt":"un ruban de caoutchouc","icone":"⬛","col":"isolant"},{"txt":"une carte marine en papier","icone":"🗺️","col":"isolant"},{"txt":"une règle en bois sec","icone":"📏","col":"isolant"}],"indices":["Dans la fiche « Conducteurs et isolants », regarde la liste des matériaux : métaux d'un côté, autres matériaux de l'autre.","Il y a quatre conducteurs : tous sont en métal (acier, fer, cuivre)."]},"timonier":{"dialogue":"Je classe tout, c'est mon métier. Mais attention : certains objets de cette table sont trompeurs. Conducteur ou isolant ? Il faut le savoir, pas le deviner.","consigne":"Classe les neuf éléments trouvés dans le carré. Attention aux pièges : ce ne sont pas seulement des métaux qui conduisent.","colonnes":[{"id":"conducteur","titre":"Conducteur","icone":"⚡"},{"id":"isolant","titre":"Isolant","icone":"🛑"}],"cartes":[{"txt":"un fil de cuivre","icone":"🧵","col":"conducteur"},{"txt":"l'aiguille d'acier d'une boussole","icone":"🧭","col":"conducteur"},{"txt":"la mine d'un crayon (graphite)","icone":"✏️","col":"conducteur"},{"txt":"l'eau de mer renversée sur la table","icone":"🌊","col":"conducteur"},{"txt":"une feuille de caoutchouc","icone":"⬛","col":"isolant"},{"txt":"une carafe en cristal","icone":"🫙","col":"isolant"},{"txt":"le cuir sec d'un fauteuil","icone":"💺","col":"isolant"},{"txt":"une ficelle sèche","icone":"🪢","col":"isolant"},{"txt":"une soucoupe en porcelaine","icone":"🍽️","col":"isolant"}],"indices":["La fiche « Conducteurs et isolants » a un encadré « Attention » : lis-le en entier.","Deux conducteurs ne sont pas des métaux : l'un sert à écrire, l'autre a mouillé la table."]},"lieutenant":{"dialogue":"Avant de couper le caoutchouc, je voudrais une classification sans faute… et une raison. Monsieur le professeur ne supporte pas les affirmations sans preuve.","consigne":"Classe les dix éléments, puis choisis la phrase de la fiche qui <b>prouve</b> que la gaine du câble doit être isolante.","colonnes":[{"id":"conducteur","titre":"Conducteur","icone":"⚡"},{"id":"isolant","titre":"Isolant","icone":"🛑"}],"cartes":[{"txt":"une lame de couteau en acier","icone":"🔪","col":"conducteur"},{"txt":"un anneau en or","icone":"💍","col":"conducteur"},{"txt":"la mine d'un crayon (graphite)","icone":"✏️","col":"conducteur"},{"txt":"l'eau de mer","icone":"🌊","col":"conducteur"},{"txt":"le corps humain (une main mouillée)","icone":"✋","col":"conducteur"},{"txt":"une gaine de caoutchouc","icone":"⬛","col":"isolant"},{"txt":"une poignée en porcelaine","icone":"🍽️","col":"isolant"},{"txt":"un manche en bois sec","icone":"🪵","col":"isolant"},{"txt":"une vitre de verre","icone":"🪟","col":"isolant"},{"txt":"l'air sec entre deux fils","icone":"💨","col":"isolant"}],"justification":{"question":"Quelle phrase de la fiche prouve que la gaine du câble doit être isolante ?","options":["Un isolant ne laisse pas passer le courant : une gaine isolante empêche le courant de s'échapper par ce qui touche le câble.","L'eau salée et le corps humain laissent passer le courant.","Un câble a une âme en métal conducteur, souvent du cuivre.","Les métaux sont de bons conducteurs."],"bonne":0},"indices":["Fiche « Conducteurs et isolants » : l'encadré « Attention » parle de l'eau et du corps humain.","Pour la justification : cherche la phrase qui parle de la gaine, pas seulement des métaux."]},"second":{"type":"qcm","dialogue":"J'ai testé chaque objet entre deux fils reliés à une pile et à un galvanomètre, dont l'aiguille bouge quand le courant passe. Mon carnet est là. À vous de conclure.","consigne":"<div class='doc-carnet'><b>Carnet d'essais de Conseil</b> (l'objet est placé entre les deux fils)<table><tr><th>Objet testé</th><th>Aiguille du galvanomètre</th></tr><tr><td>compas en acier</td><td>bouge beaucoup</td></tr><tr><td>bouchon de liège</td><td>ne bouge pas</td></tr><tr><td>eau de mer dans un verre</td><td>bouge un peu</td></tr><tr><td>eau douce distillée par le bord</td><td>ne bouge pas</td></tr><tr><td>mine de crayon</td><td>bouge</td></tr><tr><td>ruban de caoutchouc</td><td>ne bouge pas</td></tr></table></div>Réponds aux trois questions à partir du carnet et de la fiche.","questions":[{"q":"D'après le carnet, quelle phrase est exacte ?","options":["L'eau de mer laisse passer un peu le courant, l'eau douce distillée presque pas.","Toute l'eau arrête le courant.","Toute l'eau conduit aussi bien que l'acier.","La mine de crayon arrête le courant."],"bonne":0},{"q":"Pourquoi le câble dénudé posé sur la table mouillée a-t-il provoqué un court-circuit ?","options":["L'eau de mer a relié les deux fils : le courant est passé de l'un à l'autre sans traverser les lampes.","Le bois sec de la table est un très bon conducteur.","Une lampe du salon était grillée.","Les piles étaient vides."],"bonne":0},{"q":"Pour l'âme du nouveau câble, quel objet du carnet conduit le mieux le courant ?","options":["le compas en acier","la mine de crayon","l'eau de mer","le ruban de caoutchouc"],"bonne":0}],"justification":{"question":"Quelle phrase de la fiche explique ta réponse à la question 2 ?","options":["Il y a court-circuit quand les deux bornes de la pile sont reliées par un conducteur sans passer par un appareil : le fil chauffe, il peut y avoir un incendie.","L'eau très pure (distillée) laisse très mal passer le courant.","Un isolant ne laisse pas passer le courant.","Un câble a une âme en métal et une gaine isolante."],"bonne":0},"indices":["Compare les deux sortes d'eau du carnet : c'est le sel dissous qui fait la différence (fiche, encadré « Attention »).","Pour la question 2, relis dans la fiche la définition du court-circuit."]}},{"id":"e2-2","escale":2,"ordre":2,"titre":"Le tableau de laiton","decor":"machines","objet_principal":"tableau-bornes","objets_cliquables":["tableau-bornes","accumulateurs","cadrans"],"personnage_emetteur":"aronnax","probleme_narratif":"Les piles du bord sont chargées, mais pendant l'avarie l'équipage a débranché les bornes du grand tableau de laiton. Le courant ne va plus nulle part : il faut reconnecter le circuit pour rallumer le grand salon et relancer la pompe à air, sans recréer de court-circuit.","enjeu":"Tant que la pompe à air ne tourne pas, la réserve d'air du Nautilus continue de baisser.","episode_du_roman":"Partie I, ch. XII « Tout par l'électricité » : Nemo explique que l'électricité l'éclaire, le chauffe et anime ses machines, et qu'il la tire de piles au sodium.","competence_programme":"Électricité : réaliser un circuit électrique fermé ; circuits en série et en dérivation ; rôle de l'interrupteur ; court-circuit.","pourquoi_ce_savoir_ici":"Les bornes ne servent à rien si l'on ne sait pas faire une boucle fermée ; et pour que le salon ne retombe pas dans le noir à la première ampoule grillée, il faut savoir monter en dérivation.","reaction_du_decor":{"effet":"lumiere","description":"Les ampoules du tableau s'allument, le bourdonnement des bobines monte, la pompe à air ronronne ; la jauge d'air cesse de baisser."},"liberte_ou_anachronisme":"Le tableau à bornes et les ampoules sont une représentation simplifiée : Verne parle de piles au sodium et de lampes électriques ; les ampoules à filament pratiques datent de 1879 (Edison, Swan), après le roman. Écart signalé dans A-VERIFIER.md.","lecon":"circuit","type":"circuit","niveau_variantes":"Mousse : fermer la boucle d'une lampe. Matelot : pile, interrupteur, lampe et pompe en une boucle. Timonier : deux lampes qui restent indépendantes (dérivation). Lieutenant : dérivation + interrupteur qui ne commande que la pompe + justification. Second : idem + un fil de secours dangereux à repérer et retirer + justification.","mousse":{"dialogue":"Les piles sont pleines, j'entends leur bourdonnement… Mais un fil manque ! Relie les bornes pour que le courant fasse le tour et rallume le lustre.","consigne":"Clique une borne, puis une autre, pour poser un fil. Le lustre doit s'allumer. Une fois les fils posés, mets sous tension.","composants":[{"id":"P","type":"pile","libelle":"Piles du bord","x":18,"y":50},{"id":"L1","type":"lampe","libelle":"Lustre du salon","x":72,"y":50}],"fils":[{"de":"P+","a":"L1a","fixe":true}],"attendu":{"allumes":["L1"]},"indices":["Fiche « Le circuit électrique » : le courant doit faire une boucle complète, sans interruption.","Un fil part déjà de la borne + : il faut revenir à la borne − en passant par le lustre."]},"matelot":{"dialogue":"Une seule boucle suffira pour l'instant : les piles, la manette, le lustre et la pompe à air, l'un après l'autre. Et la manette doit pouvoir tout arrêter.","consigne":"Relie les bornes pour former <b>une seule boucle</b> passant par la manette, le lustre et la pompe. Ferme la manette (clique dessus), puis mets sous tension.","composants":[{"id":"P","type":"pile","libelle":"Piles du bord","x":14,"y":50},{"id":"K1","type":"interrupteur","libelle":"Manette","x":40,"y":20,"ferme":false},{"id":"L1","type":"lampe","libelle":"Lustre du salon","x":78,"y":30},{"id":"M","type":"moteur","libelle":"Pompe à air","x":52,"y":78}],"fils":[],"attendu":{"allumes":["L1","M"],"fermes":["K1"],"commande":{"K1":["L1","M"]},"serie":["L1","M"]},"indices":["Fiche « Le circuit électrique » : le courant doit faire une boucle complète. Ici, une seule boucle passe par tous les appareils, l'un après l'autre.","Une boucle : borne + → manette → lustre → pompe → borne −. N'oublie pas de fermer la manette."]},"timonier":{"dialogue":"Le capitaine exige que le salon reste éclairé même si une ampoule grille. Deux lampes, l'une au salon, l'autre dans la coursive… À vous de choisir le bon montage.","consigne":"Relie les bornes pour allumer les deux lampes. Exigence de Nemo : <b>si l'une des lampes grille, l'autre doit rester allumée</b>. Puis mets sous tension.","composants":[{"id":"P","type":"pile","libelle":"Piles du bord","x":14,"y":50},{"id":"L1","type":"lampe","libelle":"Lustre du salon","x":60,"y":22},{"id":"L2","type":"lampe","libelle":"Lampe de la coursive","x":60,"y":76}],"fils":[],"attendu":{"allumes":["L1","L2"],"independants":["L1","L2"]},"indices":["Fiche « Le circuit électrique » : compare « en série » et « en dérivation ». Lequel garde une lampe allumée si l'autre grille ?","En dérivation, chaque lampe a sa propre boucle qui revient à les piles."]},"lieutenant":{"dialogue":"Trois appareils, deux exigences. Les deux lampes doivent être indépendantes, et l'interrupteur de la pompe ne doit commander que la pompe : on doit pouvoir l'arrêter sans plonger le salon dans le noir.","consigne":"Relie les bornes : lustre, lampe de coursive et pompe fonctionnent ; les deux lampes sont indépendantes ; l'interrupteur K2 ne commande <b>que</b> la pompe. Ferme K2, puis mets sous tension. Choisis ensuite la phrase de la fiche qui justifie ton montage.","composants":[{"id":"P","type":"pile","libelle":"Piles du bord","x":10,"y":50},{"id":"L1","type":"lampe","libelle":"Lustre du salon","x":56,"y":16},{"id":"L2","type":"lampe","libelle":"Lampe de la coursive","x":56,"y":48},{"id":"K2","type":"interrupteur","libelle":"Interrupteur K2","x":40,"y":82,"ferme":false},{"id":"M","type":"moteur","libelle":"Pompe à air","x":74,"y":82}],"fils":[],"attendu":{"allumes":["L1","L2","M"],"fermes":["K2"],"independants":["L1","L2"],"commande":{"K2":["M"]}},"justification":{"question":"Quelle phrase de la fiche justifie ton montage ?","options":["En dérivation, chaque appareil a sa propre boucle : si une lampe grille, les autres restent allumées, et un interrupteur placé dans une boucle ne commande que l'appareil de cette boucle.","En série, un seul interrupteur commande tous les appareils.","Pour qu'une lampe s'allume, le courant doit faire une boucle complète.","Un circuit est ouvert quand la boucle est coupée."],"bonne":0},"indices":["Fiche « Le circuit électrique », partie « En dérivation » : dessine trois boucles qui partent toutes de les piles.","L'interrupteur K2 doit être dans la boucle de la pompe, pas dans celles des lampes."]},"second":{"dialogue":"Un matelot a posé, dans la précipitation, un « fil de secours » entre les deux bornes de les piles… C'est peut-être lui, notre incendie. Contrôlez tout avant de mettre sous tension.","consigne":"Mêmes exigences : trois appareils qui fonctionnent, lampes indépendantes, K2 ne commande que la pompe, <b>et aucun court-circuit</b>. Un fil déjà posé peut être retiré (clique dessus). Puis justifie.","composants":[{"id":"P","type":"pile","libelle":"Piles du bord","x":10,"y":50},{"id":"L1","type":"lampe","libelle":"Lustre du salon","x":56,"y":16},{"id":"L2","type":"lampe","libelle":"Lampe de la coursive","x":56,"y":48},{"id":"K2","type":"interrupteur","libelle":"Interrupteur K2","x":40,"y":82,"ferme":false},{"id":"M","type":"moteur","libelle":"Pompe à air","x":74,"y":82}],"fils":[{"de":"P+","a":"P-","fixe":false,"libelle":"fil de secours"}],"attendu":{"allumes":["L1","L2","M"],"fermes":["K2"],"independants":["L1","L2"],"commande":{"K2":["M"]}},"justification":{"question":"Pourquoi fallait-il retirer le « fil de secours » ?","options":["Il y a court-circuit quand les deux bornes de la pile sont reliées par un conducteur sans passer par un appareil : le fil chauffe, il peut y avoir un incendie.","En série, si une lampe grille, toutes s'éteignent.","Pour qu'une lampe s'allume, le courant doit faire une boucle complète.","Les métaux sont de bons conducteurs."],"bonne":0},"indices":["Fiche « Le circuit électrique », encadré « Danger » : que se passe-t-il quand on relie directement les deux bornes ?","Retire le fil qui relie + à − sans passer par aucun appareil, puis monte trois boucles en dérivation, K2 dans celle de la pompe."]}},{"id":"e2-3","escale":2,"ordre":3,"titre":"Le mur des instruments","decor":"cabine","objet_principal":"mur-instruments","objets_cliquables":["mur-instruments","bureau","hublot-cabine"],"personnage_emetteur":"nemo","probleme_narratif":"La lumière est revenue, mais l'incendie a consumé de l'air : il faut remonter en refaire provision. Les cartes ont brûlé. Nemo a rejoint la cage du pilote et, par le porte-voix, réclame des mesures que l'on ne peut lire que sur le mur d'instruments de sa chambre. Les mousses, nouveaux à bord, doivent d'abord savoir quel instrument donne quelle mesure.","enjeu":"Remonter sans connaître la profondeur ni l'état de la mer en surface, c'est risquer de jaillir trop vite ou en pleine tempête.","episode_du_roman":"Partie I, ch. XII : dans sa chambre, Nemo montre à Aronnax les instruments nécessaires à la navigation (thermomètre, baromètre, boussole, sextant, chronomètres, lunettes…) et le manomètre, qui lui donne la profondeur par la pression de l'eau. Le porte-voix vers la cage du pilote est une vraisemblance (à vérifier).","competence_programme":"Objets techniques : identifier la fonction d'usage d'un objet ; réaliser et exploiter des mesures (instruments de mesure, lecture d'une graduation).","pourquoi_ce_savoir_ici":"Sans cartes, seuls les instruments disent où l'on est : il faut savoir à quoi sert chacun pour transmettre la bonne mesure au pilote.","reaction_du_decor":{"effet":"aiguilles","description":"Les aiguilles des instruments s'animent ; le pilote reçoit les mesures."},"liberte_ou_anachronisme":"Lieutenant et Second : la règle « environ 1 atmosphère de plus tous les 10 m d'eau de mer » est une notion de collège, donnée dans la fiche (document à exploiter).","lecon":"instruments","type":"association","niveau_variantes":"Mousse : 3 instruments. Matelot : 4 (manomètre, baromètre). Timonier : 5 mesures lues à rattacher à leur instrument grâce aux unités. Lieutenant : lecture du manomètre et calcul de la profondeur + justification. Second : trois documents (manomètre, baromètre, remontée) avec pièges sur la pression de surface + justification.","mousse":{"dialogue":"Je suis à la cage du pilote. Chaque instrument de ma chambre a son rôle : dites-moi lequel regarder pour chaque renseignement.","consigne":"Relie chaque instrument au renseignement qu'il donne.","paires":[{"g":"La boussole","icone":"🧭","d":"la direction à suivre"},{"g":"Le thermomètre","icone":"🌡️","d":"la température"},{"g":"L'horloge","icone":"🕰️","d":"l'heure"}],"indices":["Ouvre la fiche « Les instruments du bord » : chaque instrument a sa ligne.","« Thermo » veut dire chaleur : le thermomètre mesure la température."]},"matelot":{"dialogue":"Ici Nemo, au porte-voix. Mes cartes ont brûlé, mes instruments sont intacts. Il me faut quatre renseignements : sur quel instrument les lire ?","consigne":"Relie chaque instrument du mur au renseignement qu'il fournit au pilote.","paires":[{"g":"La boussole","icone":"🧭","d":"la direction (le cap)"},{"g":"Le thermomètre","icone":"🌡️","d":"la température à bord"},{"g":"Le manomètre","icone":"⏲️","d":"la profondeur, grâce à la pression de l'eau"},{"g":"Le baromètre","icone":"🌀","d":"le temps qu'il fera en surface"}],"indices":["Fiche « Les instruments du bord » : lis la colonne « À quoi il sert ».","Le manomètre mesure la pression de l'eau ; plus on descend, plus elle est forte."]},"timonier":{"dialogue":"Ici Nemo, au porte-voix. Je vous dicte les cinq mesures que le pilote a notées avant la panne ; rangez chacune sous l'instrument qui l'a donnée, avant de vider les réservoirs.","consigne":"Relie chaque mesure notée par le pilote à l'instrument qui l'a donnée. Aide-toi des <b>unités</b>.","paires":[{"g":"La boussole","icone":"🧭","d":"« nord-est »"},{"g":"Le thermomètre","icone":"🌡️","d":"« 18 °C »"},{"g":"Le manomètre","icone":"⏲️","d":"« 4 atmosphères »"},{"g":"Le baromètre","icone":"🌀","d":"« 758 mm de mercure, en baisse »"},{"g":"Le chronomètre","icone":"⏱️","d":"« 10 h 42 min »"}],"indices":["Fiche « Les instruments du bord » : regarde la colonne « Unité ».","Atmosphères : pression de l'eau. Millimètres de mercure : pression de l'air."]},"lieutenant":{"type":"qcm","dialogue":"Le manomètre est la seule chose qui ne ment pas, sous la mer. Lisez-le, et dites au pilote à quelle profondeur nous sommes.","consigne":"<div class='doc-manometre' data-valeur='4' data-max='8' aria-label='Manomètre : l’aiguille indique 4 atmosphères'></div>Le manomètre du mur est gradué en atmosphères. Utilise la fiche « Les instruments du bord » (encadré « La pression sous la mer »).","questions":[{"q":"À quelle profondeur se trouve le Nautilus ?","options":["environ 30 m","environ 40 m","environ 4 m","environ 10 m"],"bonne":0},{"q":"Pendant la remontée, que fera l'aiguille du manomètre ?","options":["Elle descendra vers 1 atmosphère.","Elle montera vers 8 atmosphères.","Elle restera sur 4.","Elle tombera à 0 en surface."],"bonne":0}],"justification":{"question":"Quelle phrase de la fiche permet de répondre à la question 1 ?","options":["À la surface, l'air appuie déjà avec une pression d'environ 1 atmosphère ; ensuite, la pression augmente d'environ 1 atmosphère tous les 10 m d'eau de mer.","Le manomètre mesure la pression de l'eau, donc permet de connaître la profondeur.","Plus on descend, plus l'aiguille du manomètre monte.","La pression se mesure ici en atmosphères."],"bonne":0},"indices":["Fiche « Les instruments du bord », encadré « La pression sous la mer » : combien vaut déjà la pression en surface ?","4 atmosphères = 1 (l'air, en surface) + 3 (l'eau). Combien de mètres pour 3 atmosphères d'eau ?"]},"second":{"type":"qcm","dialogue":"Ici Nemo. Trois mesures, trois décisions. Le pilote veut des nombres et des raisons : croisez mes cadrans avec votre fiche.","consigne":"<div class='doc-manometre' data-valeur='6' data-max='8' aria-label='Manomètre : l’aiguille indique 6 atmosphères'></div><div class='doc-carnet'><b>Note du pilote</b> : « Baromètre de la cage vitrée, lors de la dernière sortie en surface : 760 mm de mercure à 8 h, 752 mm à 14 h. »</div>","questions":[{"q":"Le manomètre indique 6 atmosphères. À quelle profondeur est le Nautilus ?","options":["environ 50 m","environ 60 m","environ 6 m","environ 70 m"],"bonne":0},{"q":"Que signifie la baisse rapide du baromètre notée par le pilote ?","options":["Le mauvais temps arrivait : il faut s'attendre à une mer agitée en surface.","Le beau temps arrivait.","Le Nautilus descendait.","La température de l'eau baissait."],"bonne":0},{"q":"Pendant la remontée, le manomètre passe à 2 atmosphères. À quelle profondeur sera alors le Nautilus ?","options":["environ 10 m","environ 20 m","environ 2 m","à la surface"],"bonne":0}],"justification":{"question":"Pourquoi la réponse « environ 60 m » est-elle un piège à la question 1 ?","options":["Parce qu'à la surface, l'air appuie déjà avec environ 1 atmosphère : seules 5 atmosphères sont dues à l'eau.","Parce que la pression augmente d'environ 1 atmosphère tous les 10 m.","Parce que le manomètre mesure la pression de l'eau.","Parce que plus on descend, plus l'aiguille monte."],"bonne":0},"indices":["Fiche « Les instruments du bord » : la pression en surface n'est pas zéro.","Fiche, ligne « Baromètre » : que se passe-t-il quand la pression de l'air baisse vite ?"]}},{"id":"e2-4","escale":2,"ordre":4,"titre":"L'épure du capitaine","decor":"salon","objet_principal":"epure","objets_cliquables":["epure","hublots","orgue","vitrines"],"personnage_emetteur":"ned","probleme_narratif":"Pendant la panne, l'hélice s'est arrêtée : le Nautilus dérive. Sur le divan du salon, l'épure (plan et coupe) que Nemo a montrée plus tôt. Ned Land s'impatiente : il faut retrouver le chemin de l'énergie, des piles jusqu'à l'hélice, pour savoir quoi remettre en marche, dans quel ordre.","enjeu":"Sans hélice, le Nautilus ne peut ni se diriger ni gagner une surface sûre pour renouveler son air ; et Ned Land n'aura jamais sa chance de s'évader.","episode_du_roman":"Partie I, ch. XIII « Quelques chiffres » : assis dans le salon, Nemo montre à Aronnax une épure du Nautilus (plan, coupe, élévation) et explique que ses piles font tourner l'hélice.","competence_programme":"Objets techniques et énergie : identifier la source d'énergie d'un objet ; ordonner une chaîne d'énergie (stocker, commander, distribuer, convertir, transmettre, agir) ; formes d'énergie.","pourquoi_ce_savoir_ici":"Pour relancer une machine, il faut suivre le trajet de l'énergie dans l'ordre : on ne réenclenche pas l'hélice avant d'avoir rétabli la commande et le courant.","reaction_du_decor":{"effet":"hublots","description":"Vibration de l'hélice, les panneaux de fer des hublots glissent, l'océan apparaît éclairé par le fanal ; le Nautilus remonte et la jauge d'air se remplit."},"liberte_ou_anachronisme":"Simplification : Verne décrit des électro-aimants, leviers et engrenages plutôt qu'un « moteur électrique » ; le jeu emploie le vocabulaire de l'école. Second : le sel de la mer fournit la matière du sodium ; Verne précise que l'extraction demande du charbon (à vérifier, A-VERIFIER.md).","lecon":"chaine-energie","type":"ordre","niveau_variantes":"Mousse : 4 étapes en mots simples. Matelot : 5 étapes. Timonier : 6 étapes nommées par leur fonction. Lieutenant : texte à trous sur les formes d'énergie + justification. Second : 7 étapes depuis le sel de la mer + justification.","mousse":{"dialogue":"Tonnerre ! L'hélice ne tourne plus et on dérive. Le capitaine a laissé son plan sur le divan. Dans quel ordre l'énergie va-t-elle des piles à l'hélice ?","consigne":"Remets les étapes dans l'ordre, de la première à la dernière.","items":[{"txt":"Les piles gardent l'énergie."},{"txt":"On abaisse la manette."},{"txt":"Le moteur électrique tourne."},{"txt":"L'hélice pousse le Nautilus."}],"indices":["Fiche « La chaîne d'énergie » : l'énergie part toujours de la réserve.","L'hélice est à la fin : c'est elle qui fait avancer le navire."]},"matelot":{"dialogue":"Je ne suis qu'un harponneur, moi. Mais même un harponneur sait qu'il faut une corde avant de lancer le harpon ! Sur ce plan, d'où part l'énergie, et où arrive-t-elle ?","consigne":"Remets dans l'ordre le chemin de l'énergie, sur l'épure du Nautilus.","items":[{"txt":"Les piles au sodium","sous":"la réserve d'énergie"},{"txt":"La manette de commande","sous":"on la ferme pour laisser passer le courant"},{"txt":"Les câbles qui vont de la manette au moteur","sous":"le courant circule"},{"txt":"Le moteur électrique","sous":"il se met à tourner"},{"txt":"L'hélice","sous":"elle pousse l'eau : le Nautilus avance"}],"indices":["Fiche « La chaîne d'énergie » : source → commande → … → action.","Le courant doit passer par les câbles avant d'arriver au moteur."]},"timonier":{"dialogue":"Le capitaine m'a dit : « Une machine, c'est une chaîne ; il suffit d'un maillon cassé. » Eh bien, trouvons les maillons, et vite.","consigne":"Remets dans l'ordre les six maillons de la chaîne d'énergie de l'hélice. Chaque maillon est nommé par sa fonction.","items":[{"txt":"Les piles au sodium","sous":"stocker l'énergie"},{"txt":"La manette","sous":"commander (ouvrir ou fermer le circuit)"},{"txt":"Les câbles qui vont de la manette au moteur","sous":"distribuer le courant"},{"txt":"Le moteur électrique","sous":"convertir l'énergie électrique en mouvement de rotation"},{"txt":"L'arbre de l'hélice","sous":"transmettre la rotation"},{"txt":"L'hélice","sous":"agir : pousser l'eau pour faire avancer le Nautilus"}],"indices":["Fiche « La chaîne d'énergie » : stocker → commander → distribuer → convertir → transmettre → agir.","L'arbre relie le moteur à l'hélice : il est juste avant elle."]},"lieutenant":{"type":"trous","dialogue":"On m'a assez expliqué ce plan. Écrivez-le noir sur blanc, que je puisse le relire au mécanicien. Et sans vous tromper d'énergie !","consigne":"Complète la note de Ned Land avec les étiquettes. Certaines étiquettes ne servent pas. Puis justifie.","texte":"Les piles au sodium stockent une énergie [[chimique]] qu'elles fournissent sous forme d'énergie [[électrique]]. La manette [[commande]] le passage du courant. Les câbles conduisent le courant jusqu'au moteur, qui [[convertit]] l'énergie électrique en énergie de [[mouvement]]. L'arbre [[transmet]] la rotation à l'hélice.","etiquettes":["chimique","électrique","commande","convertit","mouvement","transmet","lumineuse","crée","stocke"],"justification":{"question":"Pourquoi ne peut-on pas dire que le moteur « crée » l'énergie ?","options":["Un objet ne crée pas d'énergie : il la reçoit d'une source et la transforme.","Le moteur convertit l'énergie électrique en énergie de mouvement.","Une pile contient une énergie chimique qu'elle fournit sous forme électrique.","Le moteur est en cuivre."],"bonne":0},"indices":["Fiche « La chaîne d'énergie », partie « Les formes d'énergie » : quelle énergie est cachée dans une pile ?","Trois étiquettes sont des pièges ; l'une d'elles dit le contraire de la dernière phrase de la fiche."]},"second":{"dialogue":"Monsieur Aronnax prétend que tout commence dans la mer. Si c'est vrai, je veux le voir sur ce plan : de l'eau salée jusqu'à l'hélice, sans un maillon de travers.","consigne":"Remets dans l'ordre les sept maillons, depuis la matière des piles racontée par Nemo jusqu'à l'hélice. Puis justifie.","items":[{"txt":"Le sel dissous dans l'eau de mer"},{"txt":"Le sodium extrait du sel"},{"txt":"Les piles au sodium"},{"txt":"La manette"},{"txt":"Les câbles qui vont de la manette au moteur"},{"txt":"Le moteur électrique"},{"txt":"L'hélice (par son arbre)"}],"justification":{"question":"Quelle phrase de la fiche montre d'où vient la matière des piles du Nautilus ?","options":["Nemo tire le sodium de ses piles du sel de l'eau de mer : la mer fournit la matière de sa réserve d'énergie.","Un objet ne crée pas d'énergie : il la reçoit d'une source et la transforme.","Une pile contient une énergie chimique qu'elle fournit sous forme électrique.","Le moteur convertit l'énergie électrique en énergie de mouvement."],"bonne":0},"indices":["Fiche « La chaîne d'énergie », encadré « Dans le roman » : d'où vient le sodium ?","Les deux premiers maillons sont avant les piles."]}}]}]},"lecons":{"_commentaire":"Bibliothèque du Nautilus : fiches de leçon courtes, rangées par rayons. Chaque fiche a trois parties : « essentiel » (tous les grades), « approfondi » (Timonier, Lieutenant, Second), « expert » (Lieutenant, Second). Les énigmes y renvoient par leur champ « lecon » ; la fiche ne donne jamais la réponse d'une énigme toute faite, mais tout ce qu'il faut pour la trouver.","rayons":[{"id":"electricite","titre":"Rayon Électricité","icone":"⚡"},{"id":"navigation","titre":"Rayon Navigation","icone":"🧭"}],"lecons":[{"id":"conducteurs-isolants","rayon":"electricite","fiche":1,"icone":"🔌","titre":"Conducteurs et isolants","escale":2,"competence":"Électricité : distinguer conducteurs et isolants ; connaître les dangers de l'électricité.","essentiel":"<p>Un <b>conducteur</b> laisse passer le courant électrique. Un <b>isolant</b> ne le laisse pas passer.</p><table class='tab-lecon'><tr><th>⚡ Conducteurs</th><th>🛑 Isolants</th></tr><tr><td>les <b>métaux</b> : fer, acier, cuivre, laiton, argent, or, aluminium</td><td>le verre, la porcelaine, le caoutchouc, le plastique, le bois sec, le liège, le papier, les plumes, le cuir sec, le tissu sec, la ficelle sèche, l'air</td></tr></table><p><b>Pour savoir</b> si un objet conduit, on le place dans un circuit (une pile, une lampe, des fils) : si la lampe s'allume, il est conducteur.</p><div class='encadre attention'><b>⚠️ Attention</b> : la <b>mine de crayon</b> (le graphite) n'est pas un métal, mais elle conduit. L'<b>eau salée</b> (l'eau de mer) et le <b>corps humain</b> laissent passer le courant : on ne touche jamais un appareil électrique avec les mains mouillées.</div>","approfondi":"<h4>Le câble électrique</h4><p>Un câble a deux parties : l'<b>âme</b>, un fil de métal conducteur (souvent du cuivre), et la <b>gaine</b>, une enveloppe isolante (caoutchouc, plastique). Un isolant ne laisse pas passer le courant : une gaine isolante empêche le courant de s'échapper par ce qui touche le câble.</p>","expert":"<h4>Eau douce, eau salée</h4><p>L'eau très pure (distillée) laisse très mal passer le courant. C'est le <b>sel dissous</b> qui rend l'eau de mer conductrice. Un galvanomètre (appareil dont l'aiguille bouge quand le courant passe) permet de voir un courant trop faible pour allumer une lampe.</p><div class='encadre danger'><b>Court-circuit</b> : il y a court-circuit quand les deux bornes de la pile sont reliées par un conducteur sans passer par un appareil : le fil chauffe, il peut y avoir un incendie.</div>","dans_le_roman":"Dans le roman, Nemo explique que l'électricité éclaire, chauffe et fait marcher toutes les machines du Nautilus (Partie I, ch. XII)."},{"id":"circuit","rayon":"electricite","fiche":2,"icone":"💡","titre":"Le circuit électrique","escale":2,"competence":"Électricité : circuit fermé, ouvert ; série et dérivation ; interrupteur ; court-circuit.","essentiel":"<p>Pour qu'une lampe s'allume, le courant doit faire une <b>boucle complète</b> : il sort par une borne de la pile, traverse la lampe et revient à l'autre borne. C'est un <b>circuit fermé</b>.</p><p>Si la boucle est coupée (fil débranché, interrupteur ouvert), le circuit est <b>ouvert</b> : la lampe reste éteinte.</p><p>L'<b>interrupteur</b> sert à ouvrir ou fermer le circuit : <b>fermé</b>, il laisse passer le courant ; <b>ouvert</b>, il l'arrête.</p><p>Quand plusieurs appareils sont branchés <b>l'un après l'autre sur une seule boucle</b>, on dit qu'ils sont <b>en série</b>.</p>","approfondi":"<h4>En série</h4><p>Tous les appareils sont sur <b>la même boucle</b>, les uns après les autres. Si une lampe grille, la boucle est coupée : <b>tout s'éteint</b>. En série, un seul interrupteur commande tous les appareils.</p><h4>En dérivation</h4><p>Chaque appareil a <b>sa propre boucle</b>, qui part de la pile et y revient. Si une lampe grille, les autres restent allumées. En dérivation, chaque appareil a sa propre boucle : si une lampe grille, les autres restent allumées, et un interrupteur placé dans une boucle ne commande que l'appareil de cette boucle.</p>","expert":"<div class='encadre danger'><b>Danger : le court-circuit</b>. Il y a court-circuit quand les deux bornes de la pile sont reliées par un conducteur sans passer par un appareil : le fil chauffe, il peut y avoir un incendie. Les appareils de cette boucle ne fonctionnent plus.</div><p>Méthode : avant de mettre sous tension, suivre du doigt chaque chemin possible de la borne + à la borne − ; chaque chemin doit traverser au moins un appareil.</p>","dans_le_roman":"Nemo tire son électricité de piles au sodium (Partie I, ch. XII). Les ampoules dessinées dans le jeu sont une simplification : les lampes à incandescence pratiques datent de 1879, dix ans après le roman."},{"id":"instruments","rayon":"navigation","fiche":1,"icone":"⏲️","titre":"Les instruments du bord","escale":2,"competence":"Objets techniques : fonction d'usage ; instruments de mesure et lecture de graduations.","essentiel":"<p>Un instrument est un objet technique. Sa <b>fonction d'usage</b>, c'est ce à quoi il sert ; on la dit avec un verbe : « il sert à… ».</p><table class='tab-lecon'><tr><th>Instrument</th><th>À quoi il sert</th><th>Unité</th></tr><tr><td>🧭 boussole</td><td>indiquer le nord, donc garder la direction à suivre (le cap)</td><td>points cardinaux</td></tr><tr><td>🌡️ thermomètre</td><td>mesurer la température (de l'air à bord, de l'eau)</td><td>degrés Celsius (°C)</td></tr><tr><td>🕰️ horloge, chronomètre</td><td>donner l'heure, mesurer une durée</td><td>heures, minutes</td></tr><tr><td>⏲️ manomètre</td><td>mesurer la pression de l'eau, donc connaître la profondeur</td><td>atmosphères</td></tr><tr><td>🌀 baromètre</td><td>mesurer la pression de l'air pour prévoir le temps : beau temps ou tempête</td><td>millimètres de mercure (aujourd'hui : hectopascals)</td></tr><tr><td>🔭 lunette</td><td>voir loin</td><td>—</td></tr></table>","approfondi":"<h4>Points cardinaux</h4><p>Nord, est, sud, ouest. Entre deux, on dit : nord-est (entre le nord et l'est), sud-est, sud-ouest, nord-ouest.</p><h4>Le baromètre</h4><p>Quand le baromètre baisse vite, le mauvais temps arrive ; quand il monte, le beau temps revient.</p>","expert":"<div class='encadre'><b>La pression sous la mer</b>. La pression se mesure ici en atmosphères. À la surface, l'air appuie déjà avec une pression d'environ 1 atmosphère ; ensuite, la pression augmente d'environ 1 atmosphère tous les 10 m d'eau de mer. Exemple : à 20 m, environ 1 + 2 = 3 atmosphères. Plus on descend, plus l'aiguille du manomètre monte ; quand on remonte, elle redescend vers 1.</div>","dans_le_roman":"Dans sa chambre, Nemo montre à Aronnax les instruments « nécessaires à la navigation » ; le manomètre lui donne la profondeur par la pression de l'eau (Partie I, ch. XII)."},{"id":"chaine-energie","rayon":"electricite","fiche":3,"icone":"⚙️","titre":"La chaîne d'énergie","escale":2,"competence":"Objets techniques et énergie : source d'énergie ; chaîne d'énergie ; formes d'énergie.","essentiel":"<p>Un objet a besoin d'<b>énergie</b> pour fonctionner. L'énergie part d'une <b>source</b> (une pile, une batterie, le vent, les muscles…) et arrive à la partie qui <b>agit</b> (la lampe qui éclaire, la roue ou l'hélice qui tourne).</p><p>Exemple d'une lampe de poche : la pile garde l'énergie → on appuie sur l'interrupteur → le courant circule dans les fils → l'ampoule s'allume.</p>","approfondi":"<h4>Les maillons de la chaîne</h4><ol><li><b>stocker</b> l'énergie (pile, batterie)</li><li><b>commander</b> : laisser passer ou non (interrupteur, manette)</li><li><b>distribuer</b> le courant (fils, câbles)</li><li><b>convertir</b> : changer l'énergie électrique en mouvement, en lumière ou en chaleur (moteur, lampe, radiateur)</li><li><b>transmettre</b> le mouvement (arbre, engrenages, chaîne, courroie)</li><li><b>agir</b> : l'effet utile (la roue tourne, l'hélice pousse l'eau)</li></ol><p class='note-fiche'>Au collège, on dira : alimenter (stocker), distribuer (l'interrupteur commande le passage), convertir, transmettre.</p>","expert":"<h4>Les formes d'énergie</h4><p>Une pile contient une énergie <b>chimique</b> qu'elle fournit sous forme <b>électrique</b>. Un moteur convertit l'énergie électrique en énergie de <b>mouvement</b> ; une lampe, en énergie <b>lumineuse</b> (et un peu de chaleur). Un objet ne crée pas d'énergie : il la reçoit d'une source et la transforme.</p><div class='encadre'><b>Dans le roman</b> : Nemo tire le sodium de ses piles du sel de l'eau de mer : la mer fournit la matière de sa réserve d'énergie. Mais extraire le sodium demande lui-même de l'énergie (dans le roman, du charbon tiré de mines sous-marines).</div>","dans_le_roman":"Dans le salon, Nemo montre à Aronnax l'épure du Nautilus et lui explique comment ses piles font tourner l'hélice (Partie I, ch. XIII)."}]},"decors-fx":{"_commentaire":"Décors : une image de fond + des effets animés + des zones cliquables, en % de l'image (x, y = coin haut-gauche ; w, h = largeur, hauteur). Cascade d'image : fichier déposé assets/images/decors/<id>.webp|.jpg|.png → image de référence de l'enseignant (champ « reference ») → décor dessiné (js/decors-secours.js, aligné sur la référence). Après dépôt d'une nouvelle image, recaler zones et effets avec outils/caler-effets.html (export JSON) ; un bloc « calages » propre à chaque source est possible : calages.depose / calages.reference / calages.secours remplacent alors zones et effets pour cette source.","version":1,"decors":{"salon":{"titre":"Le grand salon","reference":"references/style-salon-nautilus.png","ambiance":["sousMarin","salon"],"kenBurns":{"echelle":1.06,"duree":38},"effets":[{"type":"caustiques","x":30,"y":50,"w":40,"h":28,"intensite":0.55},{"type":"lueur","x":22.5,"y":15,"r":7,"couleur":"#ffcf7a","pulse":0.25},{"type":"lueur","x":73,"y":15,"r":7,"couleur":"#ffcf7a","pulse":0.25},{"type":"lueur","x":47.5,"y":6,"r":9,"couleur":"#fff1c4","pulse":0.35,"scintille":true},{"type":"lueur","x":42,"y":35,"r":5,"couleur":"#3fd2ff","pulse":0.2},{"type":"lueur","x":54,"y":35,"r":5,"couleur":"#3fd2ff","pulse":0.2},{"type":"poissons","x":39,"y":29,"w":6,"h":12,"nombre":3},{"type":"poissons","x":51.5,"y":29,"w":6,"h":12,"nombre":3},{"type":"poussiere","x":25,"y":10,"w":50,"h":60,"nombre":40},{"type":"vignette","force":0.55},{"type":"grain","force":0.05}],"zones":[{"id":"epure","libelle":"L'épure du Nautilus, sur le divan","x":40,"y":41,"w":18,"h":12,"description":"Le plan, la coupe et l'élévation du Nautilus, à l'encre bleue. Le capitaine l'a laissée là."},{"id":"hublots","libelle":"Les hublots du salon","x":37.5,"y":27,"w":7,"h":16,"description":"Derrière la vitre épaisse, l'eau sombre. Des poissons passent dans la lumière du salon."},{"id":"orgue","libelle":"Le grand orgue","x":45,"y":17,"w":6.5,"h":22,"description":"L'orgue du capitaine. Ses tuyaux montent jusqu'au plafond ; le clavier est fermé à clé."},{"id":"vitrines","libelle":"Les vitrines du musée","x":2,"y":42,"w":18,"h":28,"description":"Coraux, coquillages, étoiles de mer : Conseil les a déjà tous classés deux fois."}],"etats":{"panne":{"filtre":"brightness(.42) saturate(.6) hue-rotate(-12deg)","alarme":true},"normal":{"filtre":"none"},"victoire":{"filtre":"brightness(1.08) saturate(1.1)","ocean":true}}},"carre":{"titre":"Le carré des officiers","reference":"references/style-salle-officiers-3.png","ambiance":["sousMarin","carre"],"kenBurns":{"echelle":1.05,"duree":34},"effets":[{"type":"lueur","x":37,"y":43,"r":11,"couleur":"#b8ffb0","pulse":0.2},{"type":"lueur","x":66.5,"y":28,"r":8,"couleur":"#38c8ff","pulse":0.15},{"type":"bulles","x":62,"y":18,"w":9,"h":22,"nombre":10},{"type":"fumee","x":30,"y":70,"w":30,"h":40,"nombre":24,"etat":"panne"},{"type":"etincelles","x":13,"y":28,"etat":"panne"},{"type":"poussiere","x":15,"y":20,"w":60,"h":60,"nombre":30},{"type":"vignette","force":0.6},{"type":"grain","force":0.05}],"zones":[{"id":"table","libelle":"Les objets de la grande table","x":18,"y":60,"w":34,"h":34,"description":"Cartes roussies, compas, règles, un verre, des bouchons… Conseil a tout aligné."},{"id":"journal","libelle":"Le journal de bord","x":56,"y":78,"w":24,"h":18,"description":"Il ne reste du journal de bord que la reliure et des pages noircies. Tout sera à reconstituer."},{"id":"tableau-cadrans","libelle":"Le tableau des cadrans","x":6.5,"y":14,"w":13,"h":21,"description":"Les aiguilles des cadrans électriques sont tombées à zéro."}],"etats":{"panne":{"filtre":"brightness(.55) saturate(.75)","alarme":true},"normal":{"filtre":"none"}}},"machines":{"titre":"La salle des machines électriques","reference":null,"ambiance":["sousMarin","machines"],"kenBurns":{"echelle":1.05,"duree":30},"effets":[{"type":"lueur","x":50,"y":18,"r":14,"couleur":"#7fd8ff","pulse":0.35},{"type":"lueur","x":17,"y":62,"r":10,"couleur":"#8cf0c8","pulse":0.3},{"type":"etincelles","x":50,"y":47,"etat":"panne"},{"type":"rayons","x":50,"y":0,"w":30,"h":70},{"type":"poussiere","x":5,"y":10,"w":90,"h":70,"nombre":45},{"type":"vignette","force":0.6},{"type":"grain","force":0.06}],"zones":[{"id":"tableau-bornes","libelle":"Le grand tableau de laiton","x":34,"y":22,"w":32,"h":50,"description":"Des bornes de laiton, des fils débranchés, des ampoules éteintes."},{"id":"accumulateurs","libelle":"Les piles du Nautilus","x":3,"y":46,"w":27,"h":44,"description":"Les grandes piles au sodium du Nautilus. Elles bourdonnent doucement : elles sont chargées."},{"id":"cadrans","libelle":"Les cadrans de contrôle","x":70,"y":13,"w":23,"h":28,"description":"Les cadrans des circuits : salon, coursive, pompe à air. Tous à zéro."}],"etats":{"panne":{"filtre":"brightness(.5) saturate(.7)","alarme":true},"normal":{"filtre":"none"}}},"cabine":{"titre":"La chambre du capitaine Nemo","reference":"references/style-cabine-capitaine-2.png","ambiance":["sousMarin","cabine"],"kenBurns":{"echelle":1.05,"duree":36},"effets":[{"type":"lueur","x":57,"y":43,"r":9,"couleur":"#b8ffb0","pulse":0.2},{"type":"lueur","x":89,"y":9,"r":7,"couleur":"#ffcf7a","pulse":0.2},{"type":"caustiques","x":46,"y":6,"w":18,"h":36,"intensite":0.4},{"type":"bulles","x":48,"y":8,"w":15,"h":34,"nombre":12},{"type":"poissons","x":47,"y":8,"w":16,"h":32,"nombre":4,"meduses":true},{"type":"poussiere","x":20,"y":10,"w":60,"h":60,"nombre":25},{"type":"vignette","force":0.6},{"type":"grain","force":0.05}],"zones":[{"id":"mur-instruments","libelle":"Le mur des instruments","x":68,"y":4,"w":17,"h":42,"description":"Baromètre, horloges, manomètre, une carte du ciel : tout ce dont un capitaine a besoin."},{"id":"bureau","libelle":"Le bureau du capitaine","x":40,"y":49,"w":31,"h":20,"description":"Une loupe, un compas, des rouleaux de plans. Les cartes marines, elles, ont brûlé dans le carré."},{"id":"hublot-cabine","libelle":"Le hublot","x":46,"y":5,"w":18,"h":38,"description":"Des méduses dérivent, très près de la vitre."}],"etats":{"panne":{"filtre":"brightness(.6) saturate(.8)"},"normal":{"filtre":"none"}}}}},"dialogues":{"_commentaire":"Textes parlés (voix du navigateur + sous-titres) : cinématiques et accueil. Les textes restent ici, jamais incrustés dans les images ni les vidéos : une vidéo déposée (assets/videos/<id>.mp4) est sous-titrée avec ces lignes. Citations du roman : à vérifier sur le texte (voir A-VERIFIER.md).","accueil":{"personnage":"aronnax","texte":"Novembre 1867. Le monstre que poursuivait la frégate Abraham Lincoln n'était pas un narval géant : c'est un navire sous-marin, le Nautilus, commandé par le mystérieux capitaine Nemo. Vous, les jeunes mousses de la frégate, avez été recueillis à son bord avec Conseil, Ned Land et moi-même. Nemo nous laisse libres d'aller dans son navire… à condition de ne jamais le quitter. Aidez l'équipage, et reconstituez le journal de bord du Nautilus."},"cinematiques":{"transition-e2":{"titre":"Escale 2 — Dans le ventre du Nautilus","video":"transition-e2","plans":[{"decor":"salon","etat":"normal","duree":7,"personnage":"nemo","texte":"Voici le salon du Nautilus, professeur. Ici, tout se fait par l'électricité : elle m'éclaire, elle me chauffe, elle fait tourner mes machines.","mouvement":"zoom"},{"decor":"salon","etat":"normal","duree":5,"personnage":"aronnax","texte":"Mais d'où tirez-vous tant d'énergie, capitaine, au fond de la mer ?","mouvement":"glisse"},{"decor":"salon","etat":"panne","duree":5,"personnage":null,"texte":"Un claquement sec. Une odeur de brûlé monte du carré des officiers. Les lampes s'éteignent.","effet":"coupure","mouvement":"secousse"},{"decor":"carre","etat":"panne","duree":6,"personnage":"nemo","texte":"Un court-circuit. Le feu a dévoré mes cartes et le journal de bord… et une part de notre air. Vous êtes à bord : aidez mon équipage.","mouvement":"zoom"}]},"fin-e2":{"titre":"Le Nautilus fait surface","plans":[{"decor":"salon","etat":"victoire","duree":6,"personnage":"aronnax","texte":"Les panneaux s'ouvrent… l'océan ! Le Nautilus remonte, l'air frais entre par les écoutilles.","mouvement":"zoom"}]}},"fin_escale":{"2":{"personnage":"nemo","texte":"Mon navire vous doit une fière chandelle. Sous le divan, ma boîte de bord a échappé au feu ; sur son couvercle est gravée la devise du Nautilus. Notez-la bien : c'est la première page de notre nouveau journal."}},"sas":["La pression monte dans le sas : il se verrouille. Profitez-en pour relire la fiche.","Sas verrouillé. Un bon marin vérifie ses instruments avant d'agir : la Bibliothèque est ouverte.","Le sas se purge… Relisez la fiche de la Bibliothèque avant de réessayer."]},"personnages":{"_commentaire":"Fiches d'identité des personnages (reprises à l'identique dans PRODUCTION-MEDIAS.md) et réglages de voix. Portrait : fichier déposé assets/images/personnages/<id>.webp|.png|.jpg, sinon portrait dessiné (js/personnages.js).","personnages":{"nemo":{"nom":"Le capitaine Nemo","court":"Nemo","voix":{"rate":0.88,"pitch":0.82},"ton":"énigmatique, cultivé, grave, jamais méchant ni caricatural","fiche":"Homme d'une cinquantaine d'années, cheveux gris plaqués en arrière, barbe poivre et sel taillée, regard grave, intense et mélancolique ; long manteau (redingote) bleu marine à double rang de boutons dorés, gilet et col blancs sobres, chaîne de montre ; posture droite, mains dans le dos."},"aronnax":{"nom":"Le professeur Aronnax","court":"Aronnax","voix":{"rate":0.98,"pitch":1.0},"ton":"savant enthousiaste, curieux, précis","fiche":"Savant français d'environ 40 ans, professeur au Muséum de Paris ; cheveux bruns légèrement grisonnants aux tempes, moustache et favoris soignés, regard curieux ; redingote brune, gilet, cravate nouée, carnet de notes et crayon à la main."},"conseil":{"nom":"Conseil","court":"Conseil","voix":{"rate":0.96,"pitch":1.08},"ton":"flegmatique, poli, classe tout, vouvoie toujours","fiche":"Domestique flamand du professeur, environ 30 ans, flegmatique ; cheveux châtain clair bien peignés, rasé de près, petites lunettes rondes cerclées de métal ; tenue de serviteur soignée : veste sombre ajustée, gilet, col blanc, nœud discret."},"ned":{"nom":"Ned Land","court":"Ned Land","voix":{"rate":1.08,"pitch":0.9},"ton":"harponneur canadien, impatient, franc, jure « Tonnerre ! », veut s'évader","fiche":"Harponneur canadien d'environ 40 ans, grand et large d'épaules, visage hâlé, barbe courte rousse, sourcils épais ; bonnet de laine, chemise de marin à col ouvert, gilet de cuir, harpon à la main ou sur l'épaule."}}}};
